python - <<'PY'
import glob, re
for file in glob.glob('src/module_*.py'):
    with open(file) as f: lines=f.readlines()
    new=[]
    for line in lines:
        if re.search(r'^\s*\w+:\s*int\s*=.*', line):
            new.append(re.sub(r'(?<=\w+:\s*)int\s*=.*', 'int = 0', line))
        elif re.search(r'^\s*\w+:\s*list\[int\]\s*=.*', line):
            new.append(re.sub(r'(?<=\w+:\s*)list\[int\]\s*=.*', 'list[int] = []', line))
        elif re.search(r'^\s*\w+:\s*bool\s*=.*', line):
            new.append(re.sub(r'(?<=\w+:\s*)bool\s*=.*', 'bool = True', line))
        elif re.search(r'^\s*\w+:\s*str\s*=.*', line):
            new.append(re.sub(r'(?<=\w+:\s*)str\s*=.*', 'str = ""', line))
        elif re.search(r'^\s*\w+:\s*float\s*=.*', line):
            new.append(re.sub(r'(?<=\w+:\s*)float\s*=.*', 'float = 0.0', line))
        elif re.search(r'^\s*\w+:\s*dict\[str,int\]\s*=.*', line):
            new.append(re.sub(r'(?<=\w+:\s*)dict\[str,int\]\s*=.*', 'dict[str,int] = {}', line))
        else:
            new.append(line)
    with open(file,'w') as f: f.writelines(new)
